namespace LSE.AutoCADElectrical.Librarian;
// Adds one record to default_cat.mdb with a freshly issued (or hand-typed, verified) LSE part number.
// Same discipline as the library transaction: validate everything first, back the catalog up, take the issuance lock,
// compute the number against the live catalog and the workbook, insert, read back, write a report; on any failure
// the catalog file is restored from the backup and the report records what happened.
public static class CatalogTransactionService{
 public static string BackupRoot(AppSettings s)=>s.CatalogBackupFolder.Trim().Length>0?s.CatalogBackupFolder.Trim():Path.Combine(Path.GetDirectoryName(s.CatalogPath)??Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"LSE_Catalog_Backups");
 public static string PartColumn(AppSettings s)=>s.LsePartColumn.Trim().Length==0?"USER1":s.LsePartColumn.Trim().ToUpperInvariant();
 public static void Validate(AppSettings s,NamingStandard n,PartNumberRequest pn,CatalogAddRequest q){
  if(s.CatalogPath.Trim().Length==0)throw new InvalidOperationException("The catalog MDB path is not set (LSELIBRARYSETTINGS).");if(!File.Exists(s.CatalogPath))throw new FileNotFoundException("Catalog database was not found.",s.CatalogPath);CatalogService.ValidateColumn(PartColumn(s));
  var tab=n.Tab(pn.Tab)??throw new InvalidOperationException("Choose the workbook naming tab (the LSE category sheet) the part belongs to.");PartNumberService.Validate(n.Format,pn);
  if(!tab.Types.ContainsKey(pn.Type))throw new InvalidOperationException($"Type code {pn.Type} is not defined on the \"{tab.Name}\" tab. Defined: {string.Join(", ",tab.Types.Keys)}.");
  if(q.TableName.Trim().Length==0)throw new InvalidOperationException("Choose the AutoCAD Electrical family table.");Ace.ValidateTable(q.TableName);
  if(q.Manufacturer.Trim().Length==0||q.Catalog.Trim().Length==0)throw new InvalidOperationException("MANUFACTURER and catalog number (MPN) are required.");if(q.Manufacturer.Length>24)throw new InvalidOperationException("MANUFACTURER is limited to 24 characters.");if(q.Catalog.Length>60)throw new InvalidOperationException("CATALOG is limited to 60 characters.");
  var problems=PartNumberService.DescriptionProblems(tab,q.Description).Where(p=>!p.Contains("standard asks")).ToList();if(problems.Count>0)throw new InvalidOperationException(string.Join(Environment.NewLine,problems));
  foreach(var (name,value,max) in new[]{("TYPE",q.Type,100),("RATING",q.Rating,100),("VOLTAGE",q.Voltage,100),("USER2",q.User2,100),("USER3",q.User3,100),("TEXTVALUE",q.TextValue,255),("WEBLINK",q.WebLink,255),("WDBLKNAM",q.WdBlkNam,60)})if(value.Length>max)throw new InvalidOperationException($"{name} is limited to {max} characters.");
  if(q.WebLink.Length>0&&!(q.WebLink.StartsWith("http://",StringComparison.OrdinalIgnoreCase)||q.WebLink.StartsWith("https://",StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("WEBLINK must start with http:// or https://.");
 }
 // Read-only look at what the next number would be.
 public static PartNumberPreview Preview(AppSettings s,NamingStandard n,PartNumberRequest pn){if(!File.Exists(s.CatalogPath))throw new FileNotFoundException("Catalog database was not found.",s.CatalogPath);PartNumberService.Validate(n.Format,pn);var tab=n.Tab(pn.Tab);var svc=new CatalogService(s.CatalogPath);var existing=svc.ReadColumnStartingWith(PartColumn(s),pn.Prefix);return PartNumberService.Preview(n.Format,pn,existing,tab?.KnownPartNumbers??new List<string>());}
 // Which family tables already hold numbers with this category code (most used first), for the family hint in the dialog.
 public static List<(string Table,int Count)> FamilyUsage(AppSettings s,NamingStandard n,string category){var form=PartNumberService.StandardForm(n.Format);var svc=new CatalogService(s.CatalogPath);return svc.ReadColumnStartingWith(PartColumn(s),category).Where(v=>form.IsMatch(PartNumberService.Normalize(v.Value))).GroupBy(v=>v.Table,StringComparer.OrdinalIgnoreCase).Select(g=>(g.Key,g.Count())).OrderByDescending(g=>g.Item2).ThenBy(g=>g.Item1,StringComparer.OrdinalIgnoreCase).ToList();}
 // Stand-alone run (LSECATALOGADD): own report folder, own rollback.
 public static CatalogAddResult Execute(AppSettings s,NamingStandard n,PartNumberRequest pn,CatalogAddRequest q,Action<string>? progress=null){
  Validate(s,n,pn,q);var log=new List<string>();void Log(string m){log.Add(m);progress?.Invoke(m);}
  foreach(string m in new[]{$"Started: {DateTime.Now:s} by {Environment.UserName}@{Environment.MachineName}",$"Catalog: {s.CatalogPath}",$"Naming standard: {n.Source}"+(n.FromWorkbook?" (workbook)":" (JSON snapshot)"),$"Record: {q.Summary}",$"Part number prefix: {pn.Prefix} ({pn.Tab})"})Log(m);
  var r=Run(s,n,pn,q,Log);Log("Status: SUCCESS");foreach(string m in VaultProbe.CheckinReminder(new[]{s.CatalogPath}))Log(m);try{File.WriteAllLines(Path.Combine(r.BackupFolder,"CatalogReport.txt"),log);}catch{}r.Report=string.Join(Environment.NewLine,log);return r;}
 // The reusable core, also called from the library transaction. Backs the catalog up, issues the number, inserts and
 // verifies. On failure the catalog is restored from its backup before the exception is rethrown, so callers only have
 // to roll back their own files.
 public static CatalogAddResult Run(AppSettings s,NamingStandard n,PartNumberRequest pn,CatalogAddRequest q,Action<string> log){
  Validate(s,n,pn,q);VaultProbe.RequireWritable(new[]{s.CatalogPath});string column=PartColumn(s);string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");string backup=Path.Combine(BackupRoot(s),stamp);int suffix=0;while(Directory.Exists(backup))backup=Path.Combine(BackupRoot(s),stamp+"_"+(++suffix));Directory.CreateDirectory(backup);string catBackup=Path.Combine(backup,Path.GetFileName(s.CatalogPath));
  var tab=n.Tab(pn.Tab)!;var result=new CatalogAddResult{TableName=q.TableName,BackupFolder=backup};var gateLog=new List<string>();using var gate=IssuanceLock.Acquire(s.CatalogPath,gateLog);foreach(string m in gateLog)log(m);
  File.Copy(s.CatalogPath,catBackup,true);log("Catalog backup: "+catBackup);bool written=false;
  try{var svc=new CatalogService(s.CatalogPath);var existing=svc.ReadColumnStartingWith(column,pn.Prefix);var preview=PartNumberService.Preview(n.Format,pn,existing,tab.KnownPartNumbers);string part=preview.PartNumber;foreach(string line in preview.Explanation.Split(Environment.NewLine))log("  "+line);
   var dup=svc.FindByColumn(column,part);if(dup is not null)throw new InvalidOperationException($"Part number {part} already exists in table {dup.Value.Table} ({dup.Value.Manufacturer} {dup.Value.Catalog}).");
   if(svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException($"{q.Manufacturer} {q.Catalog} already exists in family table {q.TableName}.");
   q.User1=part;result.PartNumber=part;svc.AddRecord(q,column);written=true;
   if(!svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("Read-back verification failed after the insert.");var back=svc.FindByColumn(column,part);if(back is null||!back.Value.Table.Equals(q.TableName,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Read-back of the part number failed after the insert.");
   log($"Catalog insert into {q.TableName} ({column}={part}, {q.Manufacturer} {q.Catalog}): PASS");return result;}
  catch(Exception ex){log("ERROR: "+ex.Message);try{File.Copy(catBackup,s.CatalogPath,true);log(written?"Catalog rollback: PASS":"Catalog rollback: PASS (nothing had been written)");}catch(Exception rx){log("Catalog rollback: FAILED "+rx.Message);}try{File.WriteAllLines(Path.Combine(backup,"CatalogReport.txt"),new[]{"Record: "+q.Summary,"ERROR: "+ex});}catch{}throw;}
 }
 // ---- Symbol link: set WDBLKNAM on existing LSE rows. Second entry point into default_cat.mdb, same discipline as Run. ----
 // Checks the block name and returns the library's own spelling of it. The block must be a .dwg in the LSE or stock schematic symbol library.
 public static string ResolveSymbol(AppSettings s,LibraryStandard std,string name){name=name.Trim();if(name.Length==0)throw new InvalidOperationException("Enter the schematic symbol block name.");if(name.Length>60)throw new InvalidOperationException("WDBLKNAM is limited to 60 characters.");if(name.EndsWith(".dwg",StringComparison.OrdinalIgnoreCase)||!System.Text.RegularExpressions.Regex.IsMatch(name,@"^[A-Za-z0-9_][A-Za-z0-9_\-\.\$ ]*$"))throw new InvalidOperationException("The symbol must be a block name without folders or .dwg: "+name);
  var roots=new[]{s.SymbolLibraryFolder,s.StockSymbolLibraryFolder}.Where(f=>f.Trim().Length>0&&Directory.Exists(f)).ToList();if(roots.Count==0)throw new InvalidOperationException("No schematic symbol library folder is set or present (LSELIBRARYSETTINGS).");
  foreach(string root in roots){string? hit=LibraryTransactionService.FindByName(root,name+".dwg",std);if(hit is not null)return Path.GetFileNameWithoutExtension(hit);}
  throw new InvalidOperationException($"The symbol block {name} was not found in the schematic symbol library ({string.Join(" or ",roots)}). Nothing was changed.");}
 // One backup, one issuance lock, all-or-nothing for the batch. Only WDBLKNAM is updated; a non-empty value is replaced only when Overwrite is set; rows are never added or deleted.
 public static SymbolLinkResult SetSymbols(AppSettings s,LibraryStandard std,IReadOnlyList<SymbolLinkRequest> qs,Action<string>? progress=null){
  if(qs.Count==0)throw new InvalidOperationException("Nothing to link.");if(s.CatalogPath.Trim().Length==0||!File.Exists(s.CatalogPath))throw new FileNotFoundException("Catalog database was not found.",s.CatalogPath);string column=PartColumn(s);CatalogService.ValidateColumn(column);
  var names=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var symbols=new List<string>();foreach(var q in qs){if(q.Table.Trim().Length==0||q.Manufacturer.Trim().Length==0||q.Catalog.Trim().Length==0||q.PartNumber.Trim().Length==0)throw new InvalidOperationException("Family table, MANUFACTURER, CATALOG and part number are required to find the row: "+q.Summary);Ace.ValidateTable(q.Table.Trim());if(!names.TryGetValue(q.Symbol.Trim(),out var canon))names[q.Symbol.Trim()]=canon=ResolveSymbol(s,std,q.Symbol);symbols.Add(canon);}
  var dupe=qs.GroupBy(q=>q.Table.Trim()+"|"+q.PartNumber.Trim(),StringComparer.OrdinalIgnoreCase).FirstOrDefault(g=>g.Count()>1);if(dupe is not null)throw new InvalidOperationException("The same catalog row is listed twice: "+dupe.Key);
  var svc=new CatalogService(s.CatalogPath);
  List<(bool Write,string Previous)> Decide(){var plan=new List<(bool,string)>();for(int i=0;i<qs.Count;i++){var q=qs[i];var (rows,cur)=svc.FindSymbolRows(q.Table.Trim(),column,q.PartNumber.Trim(),q.Manufacturer.Trim(),q.Catalog.Trim());
    if(rows==0)throw new InvalidOperationException($"No catalog row matches {q.Table.Trim()} | {column}={q.PartNumber.Trim()} | {q.Manufacturer.Trim()} {q.Catalog.Trim()}. Nothing was changed.");if(rows>1)throw new InvalidOperationException($"{rows} catalog rows match {q.Table.Trim()} | {column}={q.PartNumber.Trim()} | {q.Manufacturer.Trim()} {q.Catalog.Trim()}; refusing to update an ambiguous row.");
    if(cur.Equals(symbols[i],StringComparison.OrdinalIgnoreCase)){plan.Add((false,cur));continue;}if(cur.Length>0&&!q.Overwrite)throw new InvalidOperationException($"{q.Manufacturer.Trim()} {q.Catalog.Trim()} already links symbol {cur}. Nothing was changed; confirm the overwrite to replace it.");plan.Add((true,cur));}return plan;}
  var first=Decide();var result=new SymbolLinkResult{Unchanged=first.Count(p=>!p.Write)};if(!first.Any(p=>p.Write)){result.Report="Every selected row already links the chosen symbol; nothing was written.";progress?.Invoke(result.Report);return result;}
  VaultProbe.RequireWritable(new[]{s.CatalogPath});
  string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss")+"_symbollink";string backup=Path.Combine(BackupRoot(s),stamp);int suffix=0;while(Directory.Exists(backup))backup=Path.Combine(BackupRoot(s),stamp+"_"+(++suffix));Directory.CreateDirectory(backup);result.BackupFolder=backup;string catBackup=Path.Combine(backup,Path.GetFileName(s.CatalogPath));
  var log=new List<string>{$"Started: {DateTime.Now:s} by {Environment.UserName}@{Environment.MachineName}",$"Catalog: {s.CatalogPath}",$"Part column: {column}",$"Backup folder: {backup}"};void Log(string m){log.Add(m);progress?.Invoke(m);}foreach(string m in log)progress?.Invoke(m);
  var gateLog=new List<string>();using var gate=IssuanceLock.Acquire(s.CatalogPath,gateLog);foreach(string m in gateLog)Log(m);File.Copy(s.CatalogPath,catBackup,true);Log("Catalog backup: "+catBackup);bool written=false;
  try{var plan=Decide();for(int i=0;i<qs.Count;i++)Log((plan[i].Write?(plan[i].Previous.Length>0?"Change ":"Set    "):"Same   ")+$"{qs[i].Table.Trim()} | {qs[i].Manufacturer.Trim()} | {qs[i].Catalog.Trim()} | {qs[i].PartNumber.Trim()} -> {symbols[i]}"+(plan[i].Write&&plan[i].Previous.Length>0?" (was "+plan[i].Previous+")":""));
   for(int i=0;i<qs.Count;i++){if(!plan[i].Write)continue;var q=qs[i];written=true;svc.SetSymbol(q.Table.Trim(),column,q.PartNumber.Trim(),q.Manufacturer.Trim(),q.Catalog.Trim(),symbols[i]);result.Written++;}
   for(int i=0;i<qs.Count;i++){if(!plan[i].Write)continue;var q=qs[i];var (rows,cur)=svc.FindSymbolRows(q.Table.Trim(),column,q.PartNumber.Trim(),q.Manufacturer.Trim(),q.Catalog.Trim());if(rows!=1||!cur.Equals(symbols[i],StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException($"Read-back of WDBLKNAM failed for {q.Manufacturer.Trim()} {q.Catalog.Trim()} ({q.PartNumber.Trim()}).");}
   Log($"Catalog WDBLKNAM read-back: PASS ({result.Written} written, {result.Unchanged} already correct)");Log("Status: SUCCESS");foreach(string m in VaultProbe.CheckinReminder(new[]{s.CatalogPath}))Log(m);try{File.WriteAllLines(Path.Combine(backup,"SymbolLinkReport.txt"),log);}catch{}result.Report=string.Join(Environment.NewLine,log);return result;}
  catch(Exception ex){Log("ERROR: "+ex.Message);try{File.Copy(catBackup,s.CatalogPath,true);Log(written?"Catalog rollback: PASS":"Catalog rollback: PASS (nothing had been written)");}catch(Exception rx){Log("Catalog rollback: FAILED "+rx.Message);}try{File.WriteAllLines(Path.Combine(backup,"SymbolLinkReport.txt"),log);}catch{}throw;}
 }
}
